}

terraform {
  required_providers {
    local = { source = "hashicorp/local", version = "2.5.3" }
  }
}

variable "sizes" {
  type    = map(string)
  default = { lite = "m8i.xlarge", full = "m8i.2xlarge" }
}

resource "local_file" "launch_template" {
  for_each = var.sizes
  filename = "${path.module}/out/sandbox-${each.key}.txt"
  content  = "instance_type = ${each.value}\n"
}

output "files" {
  value = [for f in local_file.launch_template : f.filename]
}

module "pool" {
  source = "./modules/pool"
  sizes  = var.sizes
}

output "files" {
  value = module.pool.files
}

